# Generated by build.py from recipe.yml for recipe smtp-send-mail-with-an-attachment. Do not edit.
set -e
cd "$(dirname "$0")"
cat > report.csv <<'EOF'
date,builds,failures
2026-11-17,44,2
2026-11-18,41,0
2026-11-19,42,3
EOF
surl --mail-domain example.com --mailbox app@example.com:apppass --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -H "Subject: Nightly build report" -H "From: app@example.com" -H "To: ann@example.com" -F "=The nightly build report is attached." -F "=@report.csv;type=text/csv;encoder=base64" -o /dev/null -w "%{response_code}\n" smtp://127.0.0.1:8080/example.com && curl -sS --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=2" | tr -d "\r" | base64 -d | cmp - report.csv && echo part 2 is report.csv
kill $(jobs -p)
